n=17;m=8
G=[[0]*n for _ in range(n)]
for r in range(n):
    for c in [m-r,m+r]:
        if 0<=c<n: G[r][c]=2
for r in range(3,n):
    for c in range(n):
        if r+c>=m+2 and (c-r-(m-4))%4==0 and G[r][c]==0:
            G[r][c]=1
for row in G: print(' '.join(map(str,row)))

